# Shared supervisor for securegate's MTProxy containers (sourced by entrypoint.sh).
# Needs DIR (mounted data dir), CONF (file generated by the gateway), NAME.
# Waits for CONF (or the DISABLED marker), runs the command, restarts it when CONF changes.
set -e
i=0
while [ ! -f "$CONF" ] && [ ! -f "$DIR/DISABLED" ]; do
  i=$((i+1))
  [ $i -gt 120 ] && { echo "$NAME: config not generated by gateway after 120s"; exit 1; }
  sleep 1
done
while [ -f "$DIR/DISABLED" ]; do
  echo "$NAME: disabled ($(cat "$DIR/DISABLED" 2>/dev/null)). Idle."
  while [ -f "$DIR/DISABLED" ]; do sleep 30; done
done

PID=""
stop() {
  [ -n "$PID" ] && kill "$PID" 2>/dev/null && wait "$PID" 2>/dev/null
  exit 0
}
trap stop TERM INT
sum() { md5sum "$CONF" 2>/dev/null | cut -d' ' -f1; }

run_supervised() {
  while true; do
    if [ -f "$DIR/DISABLED" ]; then
      echo "$NAME: disabled by gateway. Idle."
      while [ -f "$DIR/DISABLED" ]; do sleep 30; done
    fi
    CUR=$(sum)
    echo "$NAME: starting"
    "$@" &
    PID=$!
    while kill -0 "$PID" 2>/dev/null; do
      sleep 5
      NEW=$(sum)
      if [ "$NEW" != "$CUR" ]; then
        echo "$NAME: config changed - restarting"
        kill "$PID" 2>/dev/null || true
        wait "$PID" 2>/dev/null || true
        break
      fi
    done
    wait "$PID" 2>/dev/null || { echo "$NAME: exited, restarting in 3s"; sleep 3; }
    PID=""
  done
}
